/* DWARF original prototype: void ShowAlignment(CHARACTER * this, bool bShow) */

void __thiscall CHARACTER::ShowAlignment(CHARACTER *this,bool bShow)

{
  if (bShow) {
    if (this->m_iAlignment == this->m_iRealAlignment) {
      return;
    }
    this->m_iAlignment = this->m_iRealAlignment;
  }
  else {
    if (this->m_iAlignment == 0) {
      return;
    }
    this->m_iAlignment = 0;
  }
  UpdatePacket(this);
  return;
}
